use crate::{cli::Algorithm,hashing::hash_file,scanner::{files,full}};use std::{collections::HashMap,path::Path};
pub struct Group{pub hash:String,pub size:u64,pub paths:Vec<String>}
pub fn find(root:&Path,hidden:bool,ignore:&[String])->Result<Vec<Group>,String>{let mut sized:HashMap<u64,Vec<_>>=HashMap::new();for r in files(root,hidden,ignore,None)?{sized.entry(r.size).or_default().push(r)}let mut groups=Vec::new();for (size,records) in sized.into_iter().filter(|(_,v)|v.len()>1){let mut hashes:HashMap<String,Vec<String>>=HashMap::new();for r in records{let h=hash_file(&full(root,&r),Algorithm::Sha256).map_err(|e|e.to_string())?;hashes.entry(h).or_default().push(r.path)}for(hash,paths)in hashes.into_iter().filter(|(_,v)|v.len()>1){groups.push(Group{hash,size,paths})}}Ok(groups)}
